package com.kynsoft.report.infrastructure.services;
import com.kynsoft.report.domain.dto.*; import com.kynsoft.report.infrastructure.entity.*; import com.kynsoft.report.infrastructure.repository.command.*; import com.kynsoft.report.infrastructure.repository.query.*; import com.kynsoft.report.infrastructure.security.*; import jakarta.transaction.Transactional; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service @Transactional public class BancoControlService {
 @org.springframework.beans.factory.annotation.Autowired private com.kynsoft.report.domain.services.IRegistroFormasNumeradasService registroFormas;
 private final ChequeTransferenciaWriteDataJPARepository chequeWrite;private final ChequeTransferenciaReadDataJPARepository chequeRead;private final ConciliacionBancariaWriteDataJPARepository concWrite;private final ConciliacionBancariaReadDataJPARepository concRead;private final MovimientoConciliacionBancariaWriteDataJPARepository movWrite;private final MovimientoConciliacionBancariaReadDataJPARepository movRead;private final FincaReadDataJPARepository fincas;
 public BancoControlService(ChequeTransferenciaWriteDataJPARepository a,ChequeTransferenciaReadDataJPARepository b,ConciliacionBancariaWriteDataJPARepository c,ConciliacionBancariaReadDataJPARepository d,MovimientoConciliacionBancariaWriteDataJPARepository e,MovimientoConciliacionBancariaReadDataJPARepository g,FincaReadDataJPARepository f){chequeWrite=a;chequeRead=b;concWrite=c;concRead=d;movWrite=e;movRead=g;fincas=f;}
 public UUID emitir(ChequeTransferenciaRequest r){if(r==null||r.getFincaId()==null||r.getTipo()==null||r.getImporte()==null||r.getImporte()<=0||v(r.getBeneficiario())==null||v(r.getConcepto())==null)throw new IllegalArgumentException("Finca, tipo, importe, beneficiario y concepto son obligatorios.");TenantValidator.validateWriteAccess(r.getFincaId());finca(r.getFincaId());ChequeTransferencia x=new ChequeTransferencia();x.setId(UUID.randomUUID());x.setNumero(chequeWrite.siguienteNumero());x.setFincaId(r.getFincaId());x.setTipo(r.getTipo());x.setFechaEmision(r.getFechaEmision()==null?LocalDateTime.now():r.getFechaEmision());x.setNumeroDocumento(registroFormas.emitir(new EmitirFormaNumeradaRequest(x.getTipo()==TipoChequeTransferencia.CHEQUE?"CHEQUE":"TRANSFERENCIA_BANCARIA",AlcanceFormaNumerada.FINCA,x.getFincaId(),x.getFechaEmision().toLocalDate(),"CHEQUE_TRANSFERENCIA",x.getId(),TenantContext.getUsuarioId())).getNumeroFormateado());x.setImporte(r.getImporte());x.setBeneficiario(v(r.getBeneficiario()));x.setConcepto(v(r.getConcepto()));x.setReferenciaBancaria(v(r.getReferenciaBancaria()));x.setAutorizadoPor(v(r.getAutorizadoPor()));x.setEmitidoPor(v(r.getEmitidoPor()));x.setObservaciones(v(r.getObservaciones()));x.setEstado(EstadoDocumentoControl.EMITIDO);x.setUsuarioId(TenantContext.getUsuarioId());chequeWrite.save(x);return x.getId();}
 public void confirmar(UUID id,boolean cobrado,String observaciones){ChequeTransferencia x=chequeWrite.findById(id).orElseThrow(()->new IllegalArgumentException("Cheque/transferencia no encontrado."));TenantValidator.validateWriteAccess(x.getFincaId());if(x.getEstado()!=EstadoDocumentoControl.EMITIDO)throw new IllegalArgumentException("Solo se puede confirmar un documento emitido.");x.setEstado(cobrado?EstadoDocumentoControl.COBRADO:EstadoDocumentoControl.ANULADO);x.setFechaConfirmacion(LocalDateTime.now());x.setObservaciones(unir(x.getObservaciones(),(cobrado?"CONFIRMADO: ":"ANULADO: ")+v(observaciones)));chequeWrite.save(x);}
 public List<ChequeTransferencia> listarEmitidos(UUID fincaId){TenantValidator.validateReadAccess(fincaId);return chequeRead.findByFincaIdOrderByFechaEmisionDesc(fincaId);}
 public UUID registrarConciliacion(CierreConciliacionBancariaRequest r){if(r==null||r.getFincaId()==null||r.getPeriodo()==null||r.getSaldoExtracto()==null||r.getSaldoLibros()==null||v(r.getResponsable())==null)throw new IllegalArgumentException("Finca, período, saldos y responsable son obligatorios.");TenantValidator.validateWriteAccess(r.getFincaId());finca(r.getFincaId());ConciliacionBancaria c=new ConciliacionBancaria();c.setId(UUID.randomUUID());c.setNumero(concWrite.siguienteNumero());c.setFincaId(r.getFincaId());c.setPeriodo(r.getPeriodo().withDayOfMonth(1));c.setFecha(LocalDateTime.now());c.setNumeroDocumento(registroFormas.emitir(new EmitirFormaNumeradaRequest("CONCILIACION_BANCARIA",AlcanceFormaNumerada.FINCA,c.getFincaId(),c.getFecha().toLocalDate(),"CONCILIACION_BANCARIA",c.getId(),TenantContext.getUsuarioId())).getNumeroFormateado());c.setSaldoExtracto(r.getSaldoExtracto());c.setSaldoLibros(r.getSaldoLibros());c.setResponsable(v(r.getResponsable()));c.setObservaciones(v(r.getObservaciones()));c.setEstado(EstadoDocumentoControl.ABIERTA);c.setUsuarioId(TenantContext.getUsuarioId());concWrite.save(c);for(MovimientoConciliacionDto m:Optional.ofNullable(r.getMovimientos()).orElse(List.of())){if(m.getFecha()==null||!("EXTRACTO".equals(v(m.getOrigen()))||"LIBROS".equals(v(m.getOrigen())))||v(m.getDescripcion())==null||m.getImporte()==null)throw new IllegalArgumentException("Cada movimiento requiere fecha, origen EXTRACTO/LIBROS, descripción e importe.");MovimientoConciliacionBancaria x=new MovimientoConciliacionBancaria();x.setId(UUID.randomUUID());x.setConciliacionId(c.getId());x.setFecha(m.getFecha());x.setOrigen(v(m.getOrigen()));x.setDescripcion(v(m.getDescripcion()));x.setReferencia(v(m.getReferencia()));x.setImporte(m.getImporte());x.setConciliado(Boolean.TRUE.equals(m.getConciliado()));x.setObservaciones(v(m.getObservaciones()));movWrite.save(x);}return c.getId();}
 public List<ConciliacionBancaria> listarConciliaciones(UUID fincaId){TenantValidator.validateReadAccess(fincaId);return concRead.findByFincaIdOrderByPeriodoDesc(fincaId);}private void finca(UUID id){if(!fincas.existsById(id))throw new IllegalArgumentException("Finca no encontrada.");}private String v(String s){return s==null||s.trim().isBlank()?null:s.trim();}private String unir(String a,String b){if(b==null)return a;return a==null?b:a+" | "+b;}
 public ConciliacionBancariaDetalleResponse detalleConciliacion(UUID id){ConciliacionBancaria c=concRead.findById(id).orElseThrow(()->new IllegalArgumentException("Conciliación no encontrada."));TenantValidator.validateReadAccess(c.getFincaId());List<MovimientoConciliacionDto> ms=movRead.findByConciliacionIdOrderByFechaAsc(id).stream().map(x->{MovimientoConciliacionDto d=new MovimientoConciliacionDto();d.setFecha(x.getFecha());d.setOrigen(x.getOrigen());d.setDescripcion(x.getDescripcion());d.setReferencia(x.getReferencia());d.setImporte(x.getImporte());d.setConciliado(x.getConciliado());d.setObservaciones(x.getObservaciones());return d;}).toList();return ConciliacionBancariaDetalleResponse.builder().id(c.getId()).numero(c.getNumero()).fincaId(c.getFincaId()).periodo(c.getPeriodo()).fecha(c.getFecha()).saldoExtracto(c.getSaldoExtracto()).saldoLibros(c.getSaldoLibros()).diferencia(c.getSaldoExtracto()-c.getSaldoLibros()).estado(c.getEstado()).responsable(c.getResponsable()).observaciones(c.getObservaciones()).movimientos(ms).build();}
 public void cerrarConciliacion(UUID id,String observaciones){ConciliacionBancaria c=concWrite.findById(id).orElseThrow(()->new IllegalArgumentException("Conciliación no encontrada."));TenantValidator.validateWriteAccess(c.getFincaId());if(c.getEstado()!=EstadoDocumentoControl.ABIERTA)throw new IllegalArgumentException("La conciliación ya fue cerrada.");c.setEstado(EstadoDocumentoControl.CERRADA);c.setObservaciones(unir(c.getObservaciones(),v(observaciones)));concWrite.save(c);}
}
